var app = new Vue({
    el: "#app",
    delimiters: ["[[", "]]"],
    data: {
      menus: [],
    },
    methods: {
      getData() {
        const path =
          window.location.origin + "/dashboard/persistent-menu/data";
        axios
          .get(path)
          .then((response) => {
            this.menus = response.data;
          })
          .catch((error) => {
            console.log(error);
          });
      },
      addNewMenu() {
        const path = window.location.origin + "/dashboard/persistent-menu";
        axios
          .post(path)
          .then((response) => {
            this.menus = response.data;
          })
          .catch((error) => {
            console.log(error);
          });
      },
      deleteMenu(index, id) {
        const path = window.location.origin + "/dashboard/persistent-menu/"+id;
        axios
          .delete(path)
          .then((response) => {
            this.menus.splice(index, 1);
            this.$notify({
              group: 'notification',
              type: response.data["status"],
              title: response.data["title"],
              text: response.data["message"],
              duration: 2500,
              speed: 1000
            });
          })
          .catch((error) => {
            console.log(error);
          });
      },
      updateData(index) {
        const path = window.location.origin + "/dashboard/persistent-menu/"+this.menus[index].id;
        axios
          .post(path, {
            stype: this.menus[index].stype,
            title: this.menus[index].title,
            block: this.menus[index].block,
          })
          .then((response) => {
            this.$notify({
              group: 'notification',
              type: response.data["status"],
              title: response.data["title"],
              text: response.data["message"],
              duration: 2500,
              speed: 1000
            })
          })
          .catch((error) => {
            console.log(error);
          });
      },
      registerData() {
        const path = window.location.origin + "/dashboard/persistent-menu";
        axios
          .put(path)
          .then((response) => {
            this.$notify({
              group: 'notification',
              type: response.data["status"],
              title: response.data["title"],
              text: response.data["message"],
              duration: 2500,
              speed: 1000
            })
          })
          .catch((error) => {
            console.log(error);
          });
      },
      unregisterData() {
        const path = window.location.origin + "/dashboard/persistent-menu";
        axios
          .delete(path)
          .then((response) => {
            this.$notify({
              group: 'notification',
              type: response.data["status"],
              title: response.data["title"],
              text: response.data["message"],
              duration: 2500,
              speed: 1000
            })
          })
          .catch((error) => {
            console.log(error);
          });
      },
    },
    created() {
      this.getData();
    },
  });
  